13	// 本文件锁定深层嵌套输入（对象、数组交替的长链，数千层未知扩展信息）下的
14	// 两类行为：
15	//
16	//   - 合法深嵌套内容继续受支持：audit 提交、report 读回与 diff 两侧的检查
17	//     结果与没有扩展内容时逐字节一致；扩展成员不参与产物哈希、报告标识与
18	//     规则结论。
19	//   - 重复成员检查与字符合法性检查的附加内存随输入大小和最大嵌套深度线性
20	//     增长（共享路径栈），不再按深度平方复制路径；一个分支处理完后，后面
21	//     兄弟分支里的问题定位不混入前一个分支的成员名或数组下标。
22	
23	// deepNestJSON 把 leaf 包进 depth 层对象/数组交替的嵌套（{"a":[{"a":[...leaf...]}]}），
24	// 并返回 leaf 值相对嵌套根的定位路径（".a[0].a[0]..."）。
25	func deepNestJSON(depth int, leaf string) (nested string, leafPath string) {
26		var b, p strings.Builder
27		for i := 0; i < depth; i++ {
28			if i%2 == 0 {
29				b.WriteString(`{"a":`)
30				p.WriteString(".a")
31			} else {
32				b.WriteString(`[`)
33				p.WriteString("[0]")
34			}
35		}
36		b.WriteString(leaf)
37		for i := depth - 1; i >= 0; i-- {
38			if i%2 == 0 {
39				b.WriteString(`}`)
40			} else {
41				b.WriteString(`]`)
42			}
43		}
44		return b.String(), p.String()
45	}
