49	func TestParseAuditInputDeepExtensionNestUnchanged(t *testing.T) {
50		nest, _ := deepNestJSON(4000, `{"leaf":[1,2,3]}`)
51		baseline := []byte(`{
52			"artifact": {"name":"Vault","abi":"abi","bytecode":"0x1","source":"Vault.sol"},
53			"rules": [{"id":"r1","kind":"static","severity":"high","invariant":"inv","version":"1.0.0"}],
54			"invariants": {"inv": false}
55		}`)
56		deep := []byte(`{
57			"artifact": {"name":"Vault","abi":"abi","bytecode":"0x1","source":"Vault.sol"},
58			"rules": [{"id":"r1","kind":"static","severity":"high","invariant":"inv","version":"1.0.0"}],
59			"invariants": {"inv": false},
60			"mystery": ` + nest + `
61		}`)
62		a0, r0, i0, c0, err := ParseAuditInput(baseline)
63		if err != nil {
64			t.Fatalf("baseline must parse: %v", err)
65		}
66		a1, r1, i1, c1, err := ParseAuditInput(deep)
67		if err != nil {
68			t.Fatalf("thousands of nested extension layers must stay supported: %v", err)
69		}
70		rep0, err := BuildReport(a0, r0, i0, c0)
71		if err != nil {
72			t.Fatal(err)
73		}
74		rep1, err := BuildReport(a1, r1, i1, c1)
75		if err != nil {
76			t.Fatal(err)
77		}
78		if !reflect.DeepEqual(rep0, rep1) {
79			t.Fatalf("extension nest must not change the report:\n%+v\n%+v", rep0, rep1)
80		}
81		if rep1.ReportID != rep0.ReportID {
82			t.Fatalf("report id changed by extension data: %s vs %s", rep0.ReportID, rep1.ReportID)
83		}
84		if len(rep1.Findings) != 1 || rep1.Findings[0].Evidence != "invariant inv does not hold" {
85			t.Fatalf("defect and evidence must be preserved: %+v", rep1.Findings)
86		}
87	}
