89	func TestLoadStoredReportDeepExtensionNest(t *testing.T) {
90		artifact := Artifact{Name: "Vault", ABI: "abi", Bytecode: "0x1", Source: "Vault.sol"}
91		rules := []Rule{{ID: "r1", Kind: "static", Severity: "high", Invariant: "inv", Version: "1.0.0"}}
92		rep, err := BuildReport(artifact, rules, map[string]bool{"inv": false}, nil)
93		if err != nil {
94			t.Fatal(err)
95		}
96		data, err := json.Marshal(rep)
97		if err != nil {
98			t.Fatal(err)
99		}
100		// 在归档 JSON 里加入数千层嵌套的未知扩展成员：不参与标识与结论，读回必须成功。
101		nest, _ := deepNestJSON(4000, `"深"`)
102		var obj map[string]json.RawMessage
103		if err := json.Unmarshal(data, &obj); err != nil {
104			t.Fatal(err)
105		}
106		obj["mystery"] = json.RawMessage(nest)
107		ext, err := json.Marshal(obj)
108		if err != nil {
109			t.Fatal(err)
110		}
111		dir := t.TempDir()
112		if err := os.WriteFile(filepath.Join(dir, rep.ReportID+".json"), ext, 0o644); err != nil {
113			t.Fatal(err)
114		}
115		got, err := LoadReport(dir, rep.ReportID)
116		if err != nil {
117			t.Fatalf("archive with a deep extension nest must load: %v", err)
118		}
119		if !reflect.DeepEqual(got, rep) {
120			t.Fatalf("loaded report differs:\n%+v\n%+v", rep, got)
121		}
122		diff, err := DiffStore(dir, rep.ReportID, rep.ReportID)
123		if err != nil {
124			t.Fatalf("diff over deep-extension archives must work: %v", err)
125		}
126		if diff.Summary.NoChange != len(rep.Rules) || len(diff.Results) != len(rep.Rules) {
127			t.Fatalf("self-diff must report every rule unchanged: %+v", diff.Summary)
128		}
129	}
130	
131	// --- 附加内存随输入大小与最大嵌套深度线性增长 ---
132	
133	func TestWalkDeepNestMemoryGrowsLinearly(t *testing.T) {
134		walkAlloc := func(depth int) (uint64, int) {
135			nest, _ := deepNestJSON(depth, `"leaf"`)
136			data := []byte(`{"mystery":` + nest + `}`)
137			runtime.GC()
138			var before, after runtime.MemStats
139			runtime.ReadMemStats(&before)
140			if e := validateJSONCharacters(data); e != nil {
141				t.Fatalf("depth %d: legal input rejected: %v", depth, e)
142			}
143			if d := findDuplicateJSONMember(data); d != nil {
144				t.Fatalf("depth %d: legal input has no duplicate: %v", depth, d)
145			}
146			runtime.ReadMemStats(&after)
147			return after.TotalAlloc - before.TotalAlloc, len(data)
148		}
149		alloc1k, _ := walkAlloc(1000)
150		alloc4k, size4k := walkAlloc(4000)
151		// 深度变为 4 倍时，线性实现的附加内存约 4 倍；逐层复制路径的实现约 16 倍。
152		if alloc4k > alloc1k*6 {
153			t.Fatalf("walk memory grows superlinearly in depth: depth 1000 -> %d bytes, depth 4000 -> %d bytes", alloc1k, alloc4k)
154		}
155		// 附加内存不超过输入大小的固定倍数。
156		if alloc4k > uint64(size4k)*500 {
157			t.Fatalf("walk memory exceeds a constant multiple of the input: %d bytes for %d input bytes", alloc4k, size4k)
158		}
159	}
160	
161	// --- 分支处理完后，后面分支的错误定位不混入前一分支 ---
162	
