181		t.Run("duplicate in later rules entry", func(t *testing.T) {
182			data := []byte(`{"rules":[{"id":"r1","version":"1","extra":` + nest + `},{"id":"r2","id":"r2","version":"1"}]}`)
183			dup := findDuplicateJSONMember(data)
184			if dup == nil {
185				t.Fatal("duplicate in rules[1] must be found")
186			}
