189				t.Fatalf("location must name rules[1] and its id, got %q", msg)
190			}
191			if strings.Contains(msg, "extra") {
192				t.Fatalf("location must not leak the previous entry's extension branch: %q", msg)
193			}
194		})
195	
196		t.Run("duplicate in later checks entry", func(t *testing.T) {
197			data := []byte(`{"checks":[{"ruleId":"r1","extra":` + nest + `},{"ruleId":"r2","ruleId":"r2"}]}`)
198			dup := findDuplicateJSONMember(data)
199			if dup == nil {
