201			}
202			msg := duplicateMemberMessage(data, dup)
203			if !strings.HasSuffix(msg, `check record for rule "r2" (checks[1])`) {
204				t.Fatalf("location must name checks[1] and its ruleId, got %q", msg)
205			}
206		})
207	
208		t.Run("character error in later branch", func(t *testing.T) {
209			data := []byte(`{"mystery":` + nest + `,"checks":[{"note":"x\uD800y"}]}`)
210			e := validateJSONCharacters(data)
211			if e == nil {
