213			}
214			if !strings.Contains(e.Error(), ".checks[0].note") {
215				t.Fatalf("location must name the later branch's value, got %q", e.Error())
216			}
217			if strings.Contains(e.Error(), "mystery") {
218				t.Fatalf("location must not leak the finished extension branch: %q", e.Error())
219			}
220		})
221	
222		t.Run("duplicate after wide sibling array", func(t *testing.T) {
223			data := []byte(`{"arr":[[["x"]],[{"y":1,"y":2}]]}`)
224			dup := findDuplicateJSONMember(data)
