235	// --- 深嵌套内部的错误定位：完整成员路径与从零开始的数组下标 ---
236	
237	func TestDeepNestInteriorErrorLocation(t *testing.T) {
238		const depth = 60
239	
240		t.Run("duplicate member deep inside", func(t *testing.T) {
