			t.Fatalf("%s: record type and array position must remain: %q", name, msg)
		}
		if name == "nested path" && !strings.Contains(msg, "rules[0].ext") {
			t.Fatalf("%s: the nested path must remain: %q", name, msg)
		}
	}
