	data := []byte(`{
		"artifact": ` + dupBigArtifact + `,
		"rules": [
			{"id":"规则 一","kind":"static","severity":"high","severity":"low","invariant":"b","version":"1"}
		],
		"mystery": 1e1000
	}`)
